from lib import *
S = SS('g38')
steps = [
    step("GODEBUG=gctrace=1:同一个分配循环跑 1.2 s,共 460 次 GC。第 1 行:gc 1 @0.002s 4%: 0.028+1.0+0.020 ms clock, 0.28+0/1.3/0.10+0.20 ms cpu, 3->4->1 MB, 4 MB goal, 10 P。含义:墙钟三段是清扫终止(STW)0.028 ms + 并发标记 1.0 ms + 标记终止(STW)0.020 ms;CPU 时间分段是 STW + 辅助/后台/空闲标记 + STW;堆从 GC 开始时 3 MB → 标记结束时 4 MB → 存活 1 MB,目标 4 MB。460 次 GC 里,清扫终止的 STW 最大 0.045 ms、标记终止的 STW 最大 0.120 ms,并发标记的墙钟时间中位 1.400 ms。", t=tl(S(1)), done=lidx(S(1), '共 460 次 GC', 'gc 1 @0.002s'), mark=lidx(S(1), '逐段解释第 1 行', '两次 STW 耗时'), b=bars([['清扫终止 STW 最大(ms)', 0.045, '0.045'], ['标记终止 STW 最大(ms)', 0.120, '0.120'], ['并发标记中位(ms)', 1.400, '1.400']], 1.4, done=[0, 1], mark=[2]), kv=KV([['三段', '清扫终止 STW + 并发标记 + 标记终止 STW'], ['第 1 次 GC', '0.028 + 1.0 + 0.020 ms 墙钟,堆 3→4→1 MB'], ['460 次 GC', 'STW 最大 0.045 与 0.120 ms']], ['三段'])),
    step("运行时源码对这几个阶段的描述:mgc.go 开头说它是 concurrent mark and sweep that uses a write barrier,non-generational and non-compacting(非分代、非压缩);第一步清扫终止要 Stop the world;标记阶段开始时启用写屏障,Start the world 之后由调度器启动的标记 worker 与分配时的 assist 做标记工作,“The write barrier shades both the overwritten pointer and the new pointer value”,新分配的对象立刻标成黑色。mbarrier.go 说 Go 用混合屏障:Yuasa 式删除屏障(把被覆盖的引用指向的对象涂灰)加 Dijkstra 式插入屏障(把新写入的对象涂灰),伪代码 shade(*slot);if current stack is grey: shade(ptr)。", t=tl(S(2)), done=lidx(S(2), 'mgc.go:8-12', 'mgc.go:25-27'), mark=lidx(S(2), 'write barrier shades both', 'mbarrier.go:24-34', 'shade(*slot)'), kv=KV([['GC 类型', '并发标记清扫,非分代、非压缩'], ['写屏障', '混合屏障:同时 shade 被覆盖的指针与新指针(栈为灰时)'], ['新分配的对象', '标记阶段一律标成黑色'], ['STW', '清扫终止与标记终止各一次']], ['写屏障'])),
    step("写屏障在汇编里:storePtr(a.next = b)的汇编里先读 runtime.writeBarrier 标志,标志打开时调用 runtime.gcWriteBarrier2 再做 STP/MOVD 存储;storeInt(a.v = x)只有一条 MOVD R1, 8(R0)。给指针字段赋值比整数多出对标志的检查与可能的屏障调用。", t=tl(S(3)), done=lidx(S(3), 'main.storeInt', 'MOVD\tR1, 8(R0)'), mark=lidx(S(3), 'runtime.writeBarrier(SB)', 'gcWriteBarrier2', 'main.storePtr'), kv=KV([['指针赋值', '检查 runtime.writeBarrier,打开时 CALL runtime.gcWriteBarrier2'], ['整数赋值', '只有一条 MOVD,没有屏障'], ['屏障何时生效', '只在标记阶段(标志打开)']], ['指针赋值'])),
    step("写屏障的代价:200 万个节点的存活堆。GC 空闲时:指针写 a.next = b 中位 2.37 ns/次,整数写 a.val[0] = i 中位 1.01 ns/次;后台一直在调用 runtime.GC()(这段时间完成了 143 轮)时:指针写变成 17.59 ns/次(约 7.4 倍),整数写 1.11 ns/次,没有变化。标记阶段里指针写才付代价。", t=tl(S(4)), done=lidx(S(4), 'GC 空闲'), mark=lidx(S(4), '后台不停地'), b=bars([['指针写,GC 空闲 ns', 2.37, '2.37'], ['整数写,GC 空闲', 1.01, '1.01'], ['指针写,后台 GC', 17.59, '17.59'], ['整数写,后台 GC', 1.11, '1.11']], 17.59, done=[0, 1, 3], mark=[2]), kv=KV([['指针写,GC 空闲', '2.37 ns'], ['指针写,标记中', '17.59 ns(约 7.4 倍)'], ['整数写', '1.01 → 1.11 ns,不受影响'], ['这段时间', '后台完成了 143 轮 GC']], ['指针写,标记中'])),
    step("Go 1.27.1 默认的 GC 实现带 goexperiment.greenteagc(go env GOEXPERIMENT 为空,go list 的 ToolTags 里有 goexperiment.greenteagc)。同一个分配循环跑 3 次:默认构建 GC 次数 [459, 457, 463],每次运行 GC 的 CPU 时间合计 [1677.6, 1691.0, 1666.2] ms;GOEXPERIMENT=nogreenteagc 构建 GC 次数 [553, 554, 559],CPU 合计 [2170.4, 2163.0, 2240.2] ms,多约 30%;两次 STW 之和的最大值在两种构建下都约 0.19 ms。", t=tl(S(5)), done=lidx(S(5), 'go env GOEXPERIMENT', '默认(greenteagc 开)'), mark=lidx(S(5), 'GOEXPERIMENT=nogreenteagc'), b=bars([['默认 GC 次数', 459, '459'], ['nogreenteagc GC 次数', 553, '553'], ['默认 GC CPU(ms)', 1677.6, '1678'], ['nogreenteagc GC CPU(ms)', 2170.4, '2170']], 2170.4, done=[0, 2], mark=[1, 3]), kv=KV([['默认(greenteagc)', 'GC 约 459 次,GC CPU 约 1.68 s'], ['nogreenteagc', 'GC 约 553 次,GC CPU 约 2.17 s'], ['STW', '两种构建都约 0.19 ms(之和的最大值)']], ['默认(greenteagc)'])),
]
A = mkartg('g38', 38, 'Go,GC,三色标记,写屏障,gctrace,真实验证,动画演示',
    '在 Go 1.27.1 里用 gctrace、源码摘录、汇编与基准验证三色标记与写屏障:一次 GC 由清扫终止 STW、并发标记、标记终止 STW 三段组成(STW 最大 0.045 与 0.120 ms);混合写屏障同时 shade 被覆盖的指针与新指针;指针赋值的汇编里检查 runtime.writeBarrier 标志并调用 gcWriteBarrier2;标记阶段里指针写从 2.37 ns 变成 17.59 ns,整数写不变;默认的 greenteagc 实现比 nogreenteagc 的 GC CPU 时间少约 23%。',
    '并发 GC 要解决一个核心问题:程序在标记期间还在改指针,怎么保证活的对象不被漏标?答案是写屏障。这篇用 gctrace 看一次 GC 的真实形态,读运行时源码里的设计描述,在汇编里找到屏障,量出屏障的代价,并对比 Go 1.27.1 默认的新 GC 实现。',
    [('17.59 ns', '标记阶段里一次指针写的耗时(GC 空闲时是 2.37 ns);整数写不受影响'), ('0.12 ms', '460 次 GC 里标记终止 STW 的最大值'), ('-23%', 'greenteagc 对这个分配循环 GC CPU 时间的节省(1.68 s 对 2.17 s)')],
    [('三个阶段', '<p>gctrace 的每行是一次 GC:两个 STW(清扫终止、标记终止)都只有几十微秒,中间的并发标记占大部分墙钟时间,但那段时间里程序在继续运行。<code>3->4->1 MB</code> 是 GC 开始时的堆、标记结束时的堆、存活的堆。源码开头也说明了总体设计:并发、标记清扫、非分代、非压缩。</p>'),
     ('为什么需要写屏障', '<p>三色标记里,标记完成的对象是黑色,待扫描的灰色,未访问的白色;白色最后被回收。如果程序在标记期间把一个白色对象的唯一引用写进一个已经变黑的对象、同时又删掉了原来的引用,这个对象就会被漏掉。写屏障拦截每一次指针写入,保证这种情况不会发生。源码里的描述是:<b>混合屏障</b>,既 shade 被覆盖的旧指针,也(在当前栈是灰色时)shade 新写入的指针;并且标记期间新分配的对象直接标黑。</p>'),
     ('写屏障在汇编里', '<p>汇编里的指针写入先读一个全局标志:GC 不在标记时标志是关的,代价只是一次比较;标记阶段标志打开,每次指针写要调用 <code>gcWriteBarrier2</code> 记录指针。整数写没有屏障,只有一条存储指令。</p>'),
     ('屏障的代价只在标记时', '<p>实测指针写在 GC 空闲时 2.37 ns,标记阶段升到 17.59 ns(约 7.4 倍);整数写不受影响。这个实验里后台连续不停地 GC,标记阶段占了几乎所有时间,是最坏情形;实际程序里标记阶段只占一部分时间。</p>'),
     ('默认的 GC 已经不是旧实现', '<p>这个工具链的 <code>ToolTags</code> 里有 <code>goexperiment.greenteagc</code>,说明默认启用了新的标记实现。同一个分配循环里关掉它(<code>GOEXPERIMENT=nogreenteagc</code>)GC 次数更多、GC CPU 时间多约 30%,STW 暂停没有变化。新实现为什么更省我没有深入(只看了现象),上面源码摘录描述的是整体设计,不是 greenteagc 的细节。</p>')],
    steps,
    [ENV_G + '。gctrace 来自 GODEBUG=gctrace=1 的真实输出;源码摘录来自 runtime/mgc.go 与 runtime/mbarrier.go(原样);汇编来自 go build -gcflags=-S;写屏障代价的存活堆是 200 万个节点(每个 56 字节),后台线程不停调用 runtime.GC();greenteagc 对比是同一份源码用 GOEXPERIMENT=nogreenteagc 重新构建,各跑 3 次',
     '没有验证:greenteagc 与旧实现的差异细节、不同堆大小与 GOGC 下的暂停、mark assist 对程序延迟的影响(见 GC 触发一篇)、amd64 上的屏障代价、对象颜色与屏障内部缓冲(wbBuf)的实现、栈扫描与屏障的交互'],
    '三色标记与写屏障')
